    "summaryZh": "2026-08-12 百度热搜第 5 名，热度 752.0万。是什么让公交车不敢开空调？据悉，今年3月起，兰州公交集团第六客运公司出台考核办法，将公交车用电用气量和司机绩效挂钩，如超出规定的能耗标准将按一定比例扣除司机的绩效工资，导致个别司机不愿在行驶过程中开空调。企业想“降本增效”可以理解，但把账转嫁到司机绩效头上，就走偏了。",
